import{_ as r,a0 as s,w as a,s as p,ao as u,I as l,x as t,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux有問必答：如何檢查Linux上的glibc版本 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何檢查Linux上的glibc版本 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何檢查Linux上的glibc版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何檢查Linux上的glibc版本 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141125 Linux FAQs with Answers--How to check glibc version on Linux","title":"Linux有問必答：如何檢查Linux上的glibc版本","tag":"201411","desc":""},"relativePath":"201411/20141125 Linux FAQs with Answers--How to check glibc version on Linux.md","filePath":"[post].md"}'),c={name:"201411/20141125 Linux FAQs with Answers--How to check glibc version on Linux.md"};function x(g,i,b,d,L,m){const n=s("Link");return a(),p("div",null,[i[11]||(i[11]=u(`<h1 id="linux有問必答-如何檢查linux上的glibc版本" tabindex="-1">Linux有問必答：如何檢查Linux上的glibc版本 <a class="header-anchor" href="#linux有問必答-如何檢查linux上的glibc版本" aria-label="Permalink to “Linux有問必答：如何檢查Linux上的glibc版本”">​</a></h1><blockquote><p><strong>問題</strong>：我需要找出我的Linux系統上的GNU C庫（glibc）的版本，我怎樣才能檢查Linux上的glibc版本呢？</p></blockquote><p>GNU C庫（glibc）是標準C庫的GNU實現。glibc是GNU工具鏈的關鍵組件，用於和二進制工具和編譯器一起使用，為目標架構生成用户空間應用程序。</p><p>當從源碼進行構建時，一些Linux程序可能需要鏈接到某個特定版本的glibc。在這種情況下，你可能想要檢查已安裝的glibc信息以查看是否滿足依賴關係。</p><p>這裏介紹幾種簡單的方法，方便你檢查Linux上的glibc版本。</p><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h3><p>下面給出了命令列下檢查GNU C庫的簡單命令。</p><pre><code>$ ldd --version 
</code></pre><p><img src="https://farm6.staticflickr.com/5613/15631104658_940163834a_z.jpg" alt=""></p><p>在本例中，<strong>glibc</strong>版本是<strong>2.19</strong>。</p><h3 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h3><p>另一個方法是在命令列“輸入”<strong>glibc 庫的名稱</strong>（如，libc.so.6），就像命令一樣執行。</p><p>輸出結果會顯示更多關於<strong>glibc庫</strong>的詳細信息，包括glibc的版本以及使用的GNU編譯器，也提供了glibc擴展的信息。glibc變量的位置取決於Linux版本和處理器架構。</p><p>在基於Debian的64位系統上：</p><pre><code>$ /lib/x86_64-linux-gnu/libc.so.6
</code></pre><p>在基於Debian的32位系統上：</p><pre><code>$ /lib/i386-linux-gnu/libc.so.6
</code></pre><p>在基於Red Hat的64位系統上：</p><pre><code>$ /lib64/libc.so.6
</code></pre><p>在基於Red Hat的32位系統上：</p><pre><code>$ /lib/libc.so.6
</code></pre><p>下圖中是輸入glibc庫後的輸出結果樣例。</p><p><img src="https://farm8.staticflickr.com/7516/15631334667_ef50b247a4_z.jpg" alt=""></p><hr>`,24)),l("p",null,[i[1]||(i[1]=t("via: ",-1)),e(n,{href:"http://ask.xmodulo.com/check-glibc-version-linux.html"},{default:o(()=>[...i[0]||(i[0]=[t("http://ask.xmodulo.com/check-glibc-version-linux.html",-1)])]),_:1})]),l("p",null,[i[4]||(i[4]=t("譯者：",-1)),e(n,{href:"https://github.com/GOLinux"},{default:o(()=>[...i[2]||(i[2]=[t("GOLinux",-1)])]),_:1}),i[5]||(i[5]=t(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...i[3]||(i[3]=[t("wxy",-1)])]),_:1})]),l("p",null,[i[8]||(i[8]=t("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[6]||(i[6]=[t("LCTT",-1)])]),_:1}),i[9]||(i[9]=t(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:o(()=>[...i[7]||(i[7]=[t("Linux中國",-1)])]),_:1}),i[10]||(i[10]=t(" 榮譽推出",-1))])])}const _=r(c,[["render",x]]);export{T as __pageData,_ as default};
